import numpy as np
from scipy import stats
from sklearn.cluster import AgglomerativeClustering
from sklearn.metrics.pairwise import cosine_similarity

MAX_DRIVERS = 5

def design(feats):
    # Identify highly correlated pairs
    corr_pairs = []
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            if abs(np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]) >= 0.6:
                corr_pairs.append((feats.ids[i], feats.ids[j]))

    # Cluster features based on correlation
    if not corr_pairs:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Create feature similarity matrix
    n_features = len(feats.ids)
    sim_matrix = np.eye(n_features)
    feature_to_idx = {fid: i for i, fid in enumerate(feats.ids)}

    for a, b in corr_pairs:
        i, j = feature_to_idx[a], feature_to_idx[b]
        sim_matrix[i,j] = sim_matrix[j,i] = abs(np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1])

    # Cluster features using hierarchical clustering
    clustering = AgglomerativeClustering(
        n_clusters=2, 
        metric='precomputed', 
        linkage='average'
    )
    clusters = clustering.fit_predict(1-sim_matrix)

    # Find the cluster with highest mean outcome difference
    best_cluster = None
    max_diff = 0
    for c in set(clusters):
        cluster_features = [feats.ids[i] for i in range(n_features) if clusters[i] == c]
        if len(cluster_features) < 2:
            continue
        cluster_indices = [feature_to_idx[f] for f in cluster_features]
        cluster_mean_y1 = np.mean(feats.y[feats.x[:,cluster_indices].mean(axis=1) > 0])
        cluster_mean_y0 = np.mean(feats.y[feats.x[:,cluster_indices].mean(axis=1) <= 0])
        diff = cluster_mean_y1 - cluster_mean_y0
        if abs(diff) > max_diff:
            max_diff = abs(diff)
            best_cluster = cluster_features

    if not best_cluster or max_diff < 0.05:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Compute weighted score
    weights = {}
    for fid in best_cluster:
        idx = feats.column(fid)
        t_stat = stats.ttest_ind(feats.x[feats.y==1,idx], feats.x[feats.y==0,idx], equal_var=False)[0]
        weights[fid] = abs(t_stat)

    # Normalize weights
    total_weight = sum(weights.values())
    if total_weight > 0:
        weights = {k: v/total_weight for k, v in weights.items()}

    return Design(
        drivers=best_cluster[:MAX_DRIVERS],
        columns=best_cluster,
        products=(),
        loadings=weights
    )

